# num_stages=3 on pointwise kernel — pipeline overhead with no benefit
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 512, 'YBLOCK': 4}, num_warps=8, num_stages=3),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 8}, num_warps=8, num_stages=3),
        # ... all configs use num_stages=3 or 4 ...
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK, XBLOCK):
    # pointwise: single load, single store, no inner loop
    tmp0 = tl.load(in_ptr + load_idx, mask)
    tl.store(out_ptr + store_idx, tmp0, mask, eviction_policy='evict_first')

